insert into settings (key, value, label, section, unit, status, source, note) values ('agency.subcontracting', '"Agencies may use subcontractors when the agreement discloses it. No approval for each person is needed. The attorney can opt out per engagement and always sees who is working on it."'::jsonb, 'Agencies may use subcontractors when the agreement discloses it', 'Agencies', '', 'C', 'Stacey 2026-11-05 (agencies brief, step 7d)', 'Replaces the Phase 1A roles table rule against auto-approved subcontracting.') on conflict (key) do nothing;
