insert into settings (key, value, label, section, unit, status, source, note) values ('agency.own_gig_fees', '"The agency pays the 5% client-side fee. If the hired freelancer is on its bench, the agency also pays the 5% freelancer-side fee and the bench member pays none; a freelancer not on its bench pays the usual 5%."'::jsonb, 'Fees on an agency''s own gig', 'Agencies', '', 'C', 'Stacey 2026-11-05 (fee answers)', '') on conflict (key) do nothing;
insert into settings (key, value, label, section, unit, status, source, note) values ('agency.split_fees', '"The attorney pays the usual 5% client fee. The agency pays the whole 5% freelancer-side fee from its share. The bench member gets their full share."'::jsonb, 'Fees on a split milestone (attorney work assigned to a bench member)', 'Agencies', '', 'C', 'Stacey 2026-11-05 (fee answers)', 'Example: $1,000 at 30/70: the agency gets $300 minus $50 = $250, the bench member $700.') on conflict (key) do nothing;
