insert into settings (key, value, label, section, unit, status, source, note) values ('data.notice_text_sensitive', '"DELA is for operations work. Never enter sensitive data: SSNs or ITINs, government ID numbers, financial account numbers, health information, biometric data, or logins and passwords. Keep it in your own storage. To share it with someone working on a job, add a secure link to the job, never to DELA''s AI. You are responsible for what you enter."'::jsonb, 'Page notice when client details are allowed (sensitive data rule)', 'Security and sensitive data', '', 'C', 'Stacey 2026-11-07 (step 9c answers)', 'Shown instead of data.notice_text while the switch client_details_allowed is on for the member.') on conflict (key) do nothing;
