insert into features (key, side, label, unit, period, kind, status, source, note) values ('ai.runs', 'both', 'Weighted AI credits per month on Lawfecta''s key', 'runs', 'month', 'quota', 'C', 'Stacey 2026-11-10 (undecided numbers answers); was: Stacey, Decision Register v1.1 (2026-10-26); provisional', 'Provisional until costs are validated. Credits are weighted by AI cost; they are not a number of playbooks or conversations. Calls on the member''s own key do not use credits. Attorney plans since step 9b (Stacey 2026-11-06), shown to attorneys as DELA actions: Free 50, Plus 300, Pro 1,000, Business 2,500 shared by the firm. The values here are the freelancer plans, unchanged. Stacey 2026-11-10: approved for beta; review after one month of real AI cost.') on conflict (key) do nothing;
